import logging
from taf.collectors.core.factories.factory_registry import CollectorFactoryRegistry
from .factory import Factory


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CollectorSetFactory(Factory):
    _product_class = dict

    def __init__(self, available_collectors=None):
        self._available_collectors = available_collectors.copy() if available_collectors else {}

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):  # noqa: C901
        super(CollectorSetFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for collector_configuration in configuration:
            if isinstance(collector_configuration, str):
                collector_name = collector_configuration
                if collector_name in resulting_arguments:
                    continue
                elif collector_name in self._available_collectors:
                    logger.debug("collector %r is already available", collector_name)
                    resulting_arguments[collector_name] = self._available_collectors[collector_name]
                    continue
                else:
                    raise AssertionError(
                        "{collector_name!r} neither in resulting arguments {resulting_arguments} nor in available "
                        "collectors {available_collectors}".format(
                            collector_name=collector_name,
                            resulting_arguments=sorted(resulting_arguments),
                            available_collectors=sorted(self._available_collectors)))
            collector_configuration = collector_configuration.copy()
            collector_name = collector_configuration['name']
            collector_existing_arguments = {}
            if "members" in collector_configuration:
                members_configuration = collector_configuration.pop("members")
                created_collectors = self.create(
                    configuration=members_configuration)
                collector_existing_arguments["members"] = [
                    created_collectors[name]
                    for name in map(self._name, members_configuration)]
                resulting_arguments.update(created_collectors)
            if "collector" in collector_configuration:
                decorated_configuration = collector_configuration.pop("collector")
                created_collectors = self.create(
                    configuration=[decorated_configuration])
                collector_existing_arguments["collector"] = created_collectors[self._name(decorated_configuration)]
                resulting_arguments.update(created_collectors)
            if "tool" in collector_configuration:
                tool_configuration = collector_configuration.pop("tool")
                created_collectors = self.create(
                    configuration=[tool_configuration])
                collector_existing_arguments["tool"] = created_collectors[self._name(tool_configuration)]
                resulting_arguments.update(created_collectors)
            collector_type = collector_configuration.pop('type')
            factory_class = CollectorFactoryRegistry.get_instance()[collector_type]
            resulting_arguments[collector_name] = factory_class().create(
                configuration=collector_configuration,
                existing_arguments=collector_existing_arguments)
            self._available_collectors[collector_name] = resulting_arguments[collector_name]

    @staticmethod
    def _name(str_or_dict):

        if isinstance(str_or_dict, dict):
            return str_or_dict["name"]
        return str_or_dict
